CREATE TABLE audit_logs (
    id bigint GENERATED ALWAYS AS IDENTITY,
    occurred_at timestamp with time zone NOT NULL,
    actor_type character varying(32) NOT NULL,
    actor_id uuid,
    database_user character varying(128) NOT NULL,
    transaction_id bigint NOT NULL,
    operation character varying(6) NOT NULL,
    table_name character varying(128) NOT NULL,
    entity_id character varying(64) NOT NULL,
    old_values jsonb,
    new_values jsonb NOT NULL,
    CONSTRAINT pk_audit_logs PRIMARY KEY (id),
    CONSTRAINT ck_audit_logs_actor_type CHECK (actor_type IN ('Anonymous', 'Staff', 'Trainee', 'System', 'Database')),
    CONSTRAINT ck_audit_logs_operation CHECK (operation IN ('INSERT', 'UPDATE'))
);

CREATE TABLE evaluation_criteria (
    id uuid NOT NULL,
    name character varying(200) NOT NULL,
    weight numeric(9,4) NOT NULL,
    sort_order integer NOT NULL,
    CONSTRAINT pk_evaluation_criteria PRIMARY KEY (id),
    CONSTRAINT ck_evaluation_criteria_weight CHECK (weight > 0)
);

CREATE TABLE fields (
    id uuid NOT NULL,
    name character varying(100) NOT NULL,
