    pending_request_alert_days integer NOT NULL,
    CONSTRAINT pk_notification_settings PRIMARY KEY (id),
    CONSTRAINT ck_notification_settings_days CHECK (training_ending_notice_days >= 1 AND late_evaluation_reminder_days >= 1 AND pending_request_alert_days >= 1),
    CONSTRAINT ck_notification_settings_single_row CHECK (id = 1)
);

CREATE TABLE roles (
    code character varying(32) NOT NULL,
    CONSTRAINT pk_roles PRIMARY KEY (code),
    CONSTRAINT ck_roles_code CHECK (code IN ('Admin', 'HR', 'Trainee', 'Employee'))
);

CREATE TABLE employees (
    id uuid NOT NULL,
    full_name character varying(200) NOT NULL,
    email character varying(320) NOT NULL,
    department character varying(200),
    role character varying(32) NOT NULL,
    CONSTRAINT pk_employees PRIMARY KEY (id),
    CONSTRAINT ck_employees_email_normalized CHECK (email = lower(btrim(email))),
    CONSTRAINT ck_employees_role CHECK (role IN ('Admin', 'HR', 'Trainee', 'Employee')),
    CONSTRAINT ck_employees_staff_role CHECK (role IN ('Employee', 'HR', 'Admin')),
    CONSTRAINT fk_employees_roles_role FOREIGN KEY (role) REFERENCES roles (code) ON DELETE RESTRICT
);

