CREATE TABLE training_applications (
    id uuid NOT NULL,
    trainee_id uuid NOT NULL,
    field_id uuid NOT NULL,
    status character varying(32) NOT NULL,
    available_from date NOT NULL,
    available_to date NOT NULL,
    hours integer NOT NULL,
    mandatory_for_university boolean NOT NULL,
    submitted_at timestamp with time zone NOT NULL,
    decided_at timestamp with time zone,
    decided_by_id uuid,
    rejection_reason character varying(2000),
    CONSTRAINT pk_training_applications PRIMARY KEY (id),
    CONSTRAINT ck_training_applications_decision CHECK ((status IN ('Accepted', 'Rejected')) = (decided_at IS NOT NULL AND decided_by_id IS NOT NULL)),
    CONSTRAINT ck_training_applications_hours CHECK (hours > 0),
    CONSTRAINT ck_training_applications_period CHECK (available_to >= available_from),
    CONSTRAINT ck_training_applications_rejection_reason CHECK ((status = 'Rejected') = (rejection_reason IS NOT NULL)),
    CONSTRAINT ck_training_applications_status CHECK (status IN ('Submitted', 'UnderReview', 'Accepted', 'Rejected')),
    CONSTRAINT fk_training_applications_employees_decided_by_id FOREIGN KEY (decided_by_id) REFERENCES employees (id) ON DELETE RESTRICT,
    CONSTRAINT fk_training_applications_fields_field_id FOREIGN KEY (field_id) REFERENCES fields (id) ON DELETE RESTRICT,
    CONSTRAINT fk_training_applications_trainees_trainee_id FOREIGN KEY (trainee_id) REFERENCES trainees (id) ON DELETE RESTRICT
);

CREATE TABLE application_attachments (
    id uuid NOT NULL,
    application_id uuid NOT NULL,
    kind character varying(32) NOT NULL,
    file_name character varying(255) NOT NULL,
    content_type character varying(255) NOT NULL,
    size_bytes bigint NOT NULL,
    sha256 character(64) NOT NULL,
    storage_key character varying(200) NOT NULL,
    uploaded_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_application_attachments PRIMARY KEY (id),
    CONSTRAINT ck_application_attachments_kind CHECK (kind IN ('Cv', 'UniversityLetter')),
    CONSTRAINT ck_application_attachments_sha256 CHECK (sha256 ~ '^[0-9a-f]{64}$'),
    CONSTRAINT ck_application_attachments_size CHECK (size_bytes > 0),
    CONSTRAINT fk_application_attachments_training_applications_application_id FOREIGN KEY (application_id) REFERENCES training_applications (id) ON DELETE RESTRICT
);

CREATE TABLE mentor_requests (
    id uuid NOT NULL,
    employee_id uuid NOT NULL,
    application_id uuid NOT NULL,
    note character varying(2000) NOT NULL,
    status character varying(32) NOT NULL,
    requested_at timestamp with time zone NOT NULL,
    decided_at timestamp with time zone,
    decided_by_id uuid,
    CONSTRAINT pk_mentor_requests PRIMARY KEY (id),
    CONSTRAINT ck_mentor_requests_decision CHECK ((status IN ('Approved', 'Rejected')) = (decided_at IS NOT NULL AND decided_by_id IS NOT NULL)),
    CONSTRAINT ck_mentor_requests_status CHECK (status IN ('Pending', 'Approved', 'Rejected')),
    CONSTRAINT fk_mentor_requests_employees_decided_by_id FOREIGN KEY (decided_by_id) REFERENCES employees (id) ON DELETE RESTRICT,
    CONSTRAINT fk_mentor_requests_employees_employee_id FOREIGN KEY (employee_id) REFERENCES employees (id) ON DELETE RESTRICT,
    CONSTRAINT fk_mentor_requests_training_applications_application_id FOREIGN KEY (application_id) REFERENCES training_applications (id) ON DELETE RESTRICT
);

CREATE TABLE assignments (
    id uuid NOT NULL,
    application_id uuid NOT NULL,
    employee_id uuid NOT NULL,
    mentor_request_id uuid,
    start_date date NOT NULL,
    end_date date NOT NULL,
    status character varying(32) NOT NULL,
    end_reason character varying(2000),
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT pk_assignments PRIMARY KEY (id),
    CONSTRAINT ck_assignments_period CHECK (end_date >= start_date),
    CONSTRAINT ck_assignments_status CHECK (status IN ('Active', 'Completed', 'EndedEarly', 'Transferred', 'Withdrawn')),
    CONSTRAINT fk_assignments_employees_employee_id FOREIGN KEY (employee_id) REFERENCES employees (id) ON DELETE RESTRICT,
    CONSTRAINT fk_assignments_mentor_requests_mentor_request_id FOREIGN KEY (mentor_request_id) REFERENCES mentor_requests (id) ON DELETE RESTRICT,
    CONSTRAINT fk_assignments_training_applications_application_id FOREIGN KEY (application_id) REFERENCES training_applications (id) ON DELETE RESTRICT
);

